min-width:0;min-height:0;display:flex}.editor-panel{border-right:1px solid var(--border);background:#12181f}.panel-heading{border-bottom:1px solid var(--border);height:43px;color:var(--dim);letter-spacing:1px;flex-shrink:0;justify-content:space-between;align-items:center;padding:8px 16px;font-size:10px;display:flex}.panel-heading>label{align-items:center;gap:12px;min-width:0;display:flex}.panel-heading input{color:var(--text);letter-spacing:0;background:0 0;border:0;width:200px;padding:4px;font-size:12px}.panel-heading button{padding:2px 8px}.filebar{border-bottom:1px solid var(--border);align-items:center;gap:10px;padding:9px 14px;display:flex}select,input[type=text],input[type=url]{background:var(--bg);border:1px solid var(--border);border-radius:4px;min-width:0;padding:7px}#file{flex:1}.entry-label{color:var(--dim);align-items:center;gap:7px;font-size:10px;display:flex}.entry-label select{max-width:180px;font-size:11px}.editor-wrap{flex:1;min-height:0;padding-top:17px;display:flex;overflow:hidden}#line-numbers{color:#4e6072;text-align:right;user-select:none;width:48px;margin:0;padding:0 12px;font-size:13px;line-height:1.7;overflow:hidden}#editor{resize:none;tab-size:2;color:#c6e0db;white-space:pre;background:0 0;border:0;outline:none;flex:1;padding:0 18px 24px 3px;font-size:13px;line-height:1.7;overflow:auto}.editor-footer{border-top:1px solid var(--border);color:var(--dim);justify-content:space-between;gap:10px;padding:8px 14px;font-size:10px;display:flex}.score-scroll{flex:1;min-height:150px;position:relative;overflow:auto}.tracks{padding:0 16px}.track{border-bottom:1px solid var(--border);padding:13px 0 10px}.track-head{align-items:center;gap:10px;margin-bottom:8px;font-size:12px;display:flex}.track-head .track-id{text-overflow:ellipsis;white-space:nowrap;overflow:hidden}.track-head button{margin-left:auto;padding:3px 8px;font-size:10px}.track-head button[aria-pressed=true]{color:var(--accent);border-color:var(--accent)}.track-head .note-count{color:var(--dim);font-size:10px}canvas{background:#10171e;border:1px solid #222f3a;border-radius:4px;width:100%;height:82px;display:block}#empty-score{color:var(--dim);text-align:center;padding:65px 24px;font-size:12px}.console{border-top:1px solid var(--border);flex-shrink:0;height:190px}.console pre{white-space:pre-wrap;word-break:break-word;color:#a8bacb;height:140px;margin:0;padding:14px 16px;font-size:11px;line-height:1.65;overflow:auto}.console pre.error{color:var(--red)}footer{border-top:1px solid var(--border);color:var(--dim);justify-content:space-between;align-items:center;gap:10px;padding:9px 20px;font-size:10px;display:flex}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}.dot{background:var(--accent);border-radius:50%;width:6px;height:6px;margin-right:4px;display:inline-block}dialog{background:var(--panel);width:min(620px,100% - 30px);max-height:85dvh;color:var(--text);border:1px solid #465663;border-radius:9px;padding:22px;box-shadow:0 25px 80px #0009}dialog::backdrop{backdrop-filter:blur(3px);background:#02070bbb}.dialog-heading{justify-content:space-between;align-items:center;margin-bottom:20px;display:flex}h2{margin:0;font-size:17px;font-weight:500}.close{background:0 0;padding:3px 9px;font-size:20px}dialog label{color:var(--dim);flex-direction:column;gap:9px;margin:18px 0;font-size:11px;display:flex}dialog input{width:100%}dialog p{color:var(--dim);font-size:11px;line-height:1.7}dialog textarea{resize:vertical;background:var(--bg);border:1px solid var(--border);word-break:break-all;border-radius:4px;width:100%;padding:10px;font-size:11px}.dialog-actions{flex-wrap:wrap;gap:8px;margin:18px 0;display:flex}.reference-dialog{width:min(920px,100% - 30px)}#library{width:100%}#library-source{white-space:pre;background:var(--bg);border:1px solid var(--border);max-height:45dvh;padding:16px;font-size:11px;line-height:1.65;overflow:auto}[hidden]{display:none!important}body.dragging{outline:3px dashed var(--accent);outline-offset:-5px}@media (width<=1000px){.tag{display:none}.topbar{padding:12px 14px}.brand>.tag{display:none}nav{flex-wrap:wrap}.transport{padding:10px 14px}.volume{display:none}.time{margin:0 4px}footer #link-state{display:none}}@media (width<=760px){body{height:auto;min-height:100dvh}.topbar{flex-direction:column;align-items:flex-start;gap:12px;height:auto}nav{width:100%}nav button{flex:1;padding:7px}.transport{gap:6px}main{flex-direction:column;min-height:0;display:flex}.editor-panel{border-right:0;border-bottom:1px solid var(--border);height:56dvh;min-height:330px}.output-panel{min-height:400px}.score-scroll{min-height:220px;max-height:400px}footer{flex-wrap:wrap;line-height:1.5}.entry-label select{max-width:130px}}
